        "Ephrem the Syrian (365).",
        '<aside class="note-comm-ethiopian"><strong>Ephrem the Syrian</strong> <em>Commentary on Numbers</em> <small>(c. 365 AD)</small><p>On the setting-apart of the Levites for tabernacle service, Ephrem reads the census-and-separation pattern of Num 1:50 as the canonical model for ordered ministry: the people are numbered for their tribes, but one tribe is numbered for the Lord himself. The Levites&#x27; exemption from the military census is not privilege but conscription into a more dangerous service — the daily handling of the holy things. Tewahedo monastic theology cites Num 1:50 as the Old-Testament warrant for the consecration of the däbtära and the priest-monks; the consecrated are numbered for the sanctuary first, for the nation only afterward.</p></aside>',
