        3,
        "",
        "wine and strong drink",
        "word",
        "Hebrew",
        "Hebrew",
        "<strong>Nazir (<em>נָזִיר</em>) — “consecrated, separated.”</strong> The Nazirite vow was a temporary lay form of priestly-grade holiness available to anyone — male or female. Three abstentions: grape products (the abundance of the land), corpse-contact (boundary with death), and razor (visible token of separation, the long hair). Samson, Samuel, and arguably John the Baptist were lifelong Nazirites. Paul takes a temporary one in Acts 18:18, 21:23–26 — evidence that the institution survived into the first century.",
        "User original",
