        "",
        "complaining in the ears of Yahweh",
        "word",
        "Hebrew",
        "Hebrew",
        "<strong>Mit‘onenim (<em>מִתְאֹנְנִים</em>).</strong> A rare hithpolel form, a self-grumbling: complaining for complaint’s sake, without specific cause. The chapter then names the place <em>Tav‘erah</em> (“burning”) for the divine fire. Numbers 11–25 is the long arc of the wilderness murmurings — eight episodes, each a variation on the same theme: the people preferred the security of slavery to the uncertainty of freedom.",
        "User original",
