    (
        12,
        3,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Ephrem the Syrian",
        "Ephrem the Syrian (365).",
        '<aside class="note-comm-ethiopian"><strong>Ephrem the Syrian</strong> <em>Commentary on Numbers</em> <small>(c. 365 AD)</small><p>On &#x27;Moses was very meek, above all the men which were upon the face of the earth&#x27; (Num 12:3), Ephrem reads the meekness-of-Moses note as the canonical Old-Testament prefigurement of the Beatitude &#x27;blessed are the meek&#x27; (Mt 5:5) and of Christ&#x27;s own &#x27;I am meek and lowly of heart&#x27; (Mt 11:29). Moses&#x27; meekness is not weakness but the refusal to defend himself against his own sister and brother; the Lord defends him because he will not. Tewahedo monastic spirituality cites Num 12:3 as the canonical Old-Testament anchor for the cardinal monastic virtue of mätayāqǝbǝr (humility) — the desert father is meek in the pattern of Moses.</p></aside>',
        "Ephrem the Syrian, Commentary on Numbers, on 12:1-15. NPNF Series 2, vol. 13. PD.",
    ),
