    (
        12,
        7,
        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Ephrem the Syrian",
        "Ephrem the Syrian (365).",
        '<aside class="note-comm-ethiopian"><strong>Ephrem the Syrian</strong> <em>Commentary on Numbers</em> <small>(c. 365 AD)</small><p>On &#x27;My servant Moses... is faithful in all mine house&#x27; (Num 12:7), Ephrem reads the Lord&#x27;s defense of Moses as the canonical typological seed of Hebrews 3:5-6: Moses is faithful as a servant in the house, Christ as a son over the house. The household-of-God image is rooted here; the apostolic writer&#x27;s distinction between servant and son is exegetically inevitable from Num 12:7&#x27;s vocabulary. Tewahedo christology cites Num 12:7 + Heb 3 as the canonical doubled-witness that Moses prefigures but does not equal the Son who built the house — the typological gap is preserved.</p></aside>',
        "Ephrem the Syrian, Commentary on Numbers, on 12:6-8. NPNF Series 2, vol. 13. PD. Cf. Heb 3:5-6.",
    ),
