    (
        14,
        18,
        "e",
        "",
        "comm-ethiopian",
        "Tewahedo — Ephrem the Syrian",
        "Ephrem the Syrian (365).",
        '<aside class="note-comm-ethiopian"><strong>Ephrem the Syrian</strong> <em>Commentary on Numbers</em> <small>(c. 365 AD)</small><p>On Moses&#x27; citation of the divine self-disclosure &#x27;The Lord is longsuffering, and of great mercy, forgiving iniquity and transgression... by no means clearing the guilty&#x27; (Num 14:18), Ephrem reads the formula as the canonical liturgical prayer-of-pardon adopted into the Septuagint Psalter (Ps 86:15, 103:8, 145:8) and extended into every later Christian confession-rite. The verse holds together the two halves of the Name: mercy and justice, neither cancelling the other. Tewahedo penance liturgy (näsḫa-of-näsḫa) cites Num 14:18 as the canonical Old-Testament anchor for the priestly absolution formula; the same formula governs the Lenten qǝne and the Holy Thursday foot-washing.</p></aside>',
        "Ephrem the Syrian, Commentary on Numbers, on 14:13-25. NPNF Series 2, vol. 13. PD.",
    ),
