    (
        19,
        2,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Ephrem the Syrian",
        "Ephrem the Syrian (365).",
        '<aside class="note-comm-ethiopian"><strong>Ephrem the Syrian</strong> <em>Commentary on Numbers</em> <small>(c. 365 AD)</small><p>On the red heifer &#x27;wherein is no blemish, and upon which never came yoke&#x27; (Num 19:2), Ephrem reads the unyoked, unblemished, wholly-burnt red heifer as the canonical Old-Testament type of Christ&#x27;s atoning sacrifice — taken up explicitly by Hebrews 9:13-14 as the lesser-to-greater argument: if the ashes of a heifer sanctified the flesh, how much more shall the blood of Christ purge the conscience. The red colour anticipates the blood, the unyoked freedom anticipates Christ&#x27;s voluntary submission, the outside-the-camp burning anticipates Calvary outside Jerusalem (Heb 13:11-12). Tewahedo eucharistic theology cites Num 19 + Heb 9 as canonical doubled-witness to Christ&#x27;s once-for-all purifying sacrifice.</p></aside>',
        "Ephrem the Syrian, Commentary on Numbers, on 19:1-22. NPNF Series 2, vol. 13. PD. Cf. Heb 9:13-14, 13:11-12.",
    ),
