    (
        20,
        11,
        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Ephrem the Syrian",
        "Ephrem the Syrian (365).",
        '<aside class="note-comm-ethiopian"><strong>Ephrem the Syrian</strong> <em>Commentary on Numbers</em> <small>(c. 365 AD)</small><p>On Moses&#x27; striking of the rock twice at Meribah (Num 20:11), Ephrem reads the doubled-strike as the proximate cause of Moses&#x27; exclusion from the land: the Lord had commanded that he speak to the rock, not strike it. The exegetical key, taken up by Paul (1 Cor 10:4 — &#x27;that Rock was Christ&#x27;), is that Christ is struck once for the people&#x27;s salvation; to strike him twice violates the typology of the once-for-all sacrifice (Heb 9:28, 10:10). Tewahedo christology cites Num 20:11 + 1 Cor 10:4 + Heb 9-10 as the canonical triple-witness that the Rock-Christ is smitten once and yields life-giving water forever.</p></aside>',
        "Ephrem the Syrian, Commentary on Numbers, on 20:1-13. NPNF Series 2, vol. 13. PD. Cf. 1 Cor 10:4; Heb 9:28.",
    ),
