    (
        22,
        28,
        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Ephrem the Syrian",
        "Ephrem the Syrian (365).",
        '<aside class="note-comm-ethiopian"><strong>Ephrem the Syrian</strong> <em>Commentary on Numbers</em> <small>(c. 365 AD)</small><p>On the Lord&#x27;s opening of the mouth of Balaam&#x27;s ass to rebuke the prophet (Num 22:28), Ephrem reads the wonder as the canonical anchor of the doctrine that the Lord may speak truth from the most unworthy vessels: a Gentile diviner is humbled by his own beast, and the prophecy that follows (Num 24:17) issues from the same mouth that needed an ass&#x27;s instruction. The verse becomes the typological seed of 2 Peter 2:16&#x27;s denunciation of Balaam — and of the broader patristic principle that the prophetic gift can pass through mouths whose private life condemns them. Tewahedo pastoral theology cites Num 22:28 as the canonical Old-Testament anchor: receive the word for its truth, not for the messenger&#x27;s worthiness.</p></aside>',
        "Ephrem the Syrian, Commentary on Numbers, on 22:21-35. NPNF Series 2, vol. 13. PD. Cf. 2 Pet 2:16.",
    ),
