    (
        27,
        18,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Ephrem the Syrian",
        "Ephrem the Syrian (365).",
        '<aside class="note-comm-ethiopian"><strong>Ephrem the Syrian</strong> <em>Commentary on Numbers</em> <small>(c. 365 AD)</small><p>On the Lord&#x27;s selection of Joshua as Moses&#x27; successor — &#x27;Take thee Joshua the son of Nun, a man in whom is the spirit, and lay thine hand upon him&#x27; (Num 27:18) — Ephrem reads the laying-on-of-hands as the canonical Old-Testament antecedent of apostolic succession: the spirit-bearing successor is consecrated by the laying-on of the predecessor&#x27;s hands, ratified by the assembly. The transmission is bodily and visible, not merely charismatic. Tewahedo episcopal-consecration cites Num 27:18 + 1 Tim 4:14 as the canonical doubled-witness for the unbroken chain of laying-on-of-hands that grounds the Patriarchate of Ethiopia in apostolic-Mosaic continuity.</p></aside>',
        "Ephrem the Syrian, Commentary on Numbers, on 27:12-23. NPNF Series 2, vol. 13. PD. Cf. 1 Tim 4:14, 2 Tim 1:6.",
    ),
